import java.util.ArrayList;

/**
 * Character - the PARENT class for every person or monster in the game.
 *
 * Students: you will write SUBCLASSES of Character (Player, Boss,
 * Shopkeeper, Goblin, ...). You do NOT edit this file. Instead, you
 * "override" the methods marked  <-- OVERRIDE ME  to change behavior.
 *
 * NOTE: Because this class is named Character, it hides Java's built-in
 * java.lang.Character. If you ever need the built-in one (for example
 * Character.isDigit), write java.lang.Character.isDigit instead.
 */
public class Character
{
    // ------------------------------------------------------------
    // Instance variables are PRIVATE (encapsulation).
    // Subclasses must use the getter/setter methods below.
    // ------------------------------------------------------------
    private String name;
    private int health;
    private int maxHealth;
    private int strength;
    private int gold;
    private ArrayList<Item> inventory;

    /**
     * Constructor.
     * Subclasses call this with:  super(name, maxHealth, strength);
     */
    public Character(String name, int maxHealth, int strength)
    {
        this.name = name;
        this.maxHealth = maxHealth;
        this.health = maxHealth;        // starts at full health
        this.strength = strength;
        this.gold = 0;
        this.inventory = new ArrayList<Item>();
    }

    // ------------------------------------------------------------
    // Accessor methods (getters)
    // ------------------------------------------------------------

    public String getName()
    {
        return name;
    }

    public int getHealth()
    {
        return health;
    }

    public int getMaxHealth()
    {
        return maxHealth;
    }

    public int getStrength()
    {
        return strength;
    }

    public int getGold()
    {
        return gold;
    }

    public ArrayList<Item> getInventory()
    {
        return inventory;
    }

    public boolean isAlive()
    {
        return health > 0;
    }

    // ------------------------------------------------------------
    // Mutator methods (setters and helpers that change the object)
    // ------------------------------------------------------------

    public void setStrength(int newStrength)
    {
        strength = newStrength;
    }

    public void addGold(int amount)
    {
        gold += amount;
    }

    /**
     * Try to spend gold.
     * Returns true if the character had enough gold (and it was spent),
     * or false if they could not afford it.
     */
    public boolean spendGold(int amount)
    {
        if (amount > gold)
        {
            return false;
        }
        gold -= amount;
        return true;
    }

    public void addItem(Item item)
    {
        inventory.add(item);
    }

    public void removeItem(Item item)
    {
        inventory.remove(item);
    }

    /**
     * Restore health, but never go above maxHealth.
     */
    public void heal(int amount)
    {
        health += amount;
        if (health > maxHealth)
        {
            health = maxHealth;
        }
        System.out.println(name + " heals " + amount + " health. ("
                           + health + "/" + maxHealth + ")");
    }

    // ------------------------------------------------------------
    // Fighting
    // ------------------------------------------------------------

    /**
     * Figure out how much damage one attack does.
     * Damage = strength + best attack bonus from the inventory + a dice roll (1-6).
     * (Notice this loop works on ANY kind of Item - that is polymorphism!)
     */
    public int getAttackDamage()
    {
        int bestBonus = 0;
        for (Item item : inventory)
        {
            if (item.getAttackBonus() > bestBonus)
            {
                bestBonus = item.getAttackBonus();
            }
        }
        int roll = (int)(Math.random() * 6) + 1;
        return strength + bestBonus + roll;
    }

    /**
     * How much damage this character blocks, based on the best defense
     * bonus in the inventory.
     */
    public int getDefense()
    {
        int bestDefense = 0;
        for (Item item : inventory)
        {
            if (item.getDefenseBonus() > bestDefense)
            {
                bestDefense = item.getDefenseBonus();
            }
        }
        return bestDefense;
    }

    /**
     * Attack another character.
     */
    public void attack(Character target)
    {
        int damage = getAttackDamage();
        System.out.println(name + " attacks " + target.getName() + "!");
        target.takeDamage(damage);
    }

    /**
     * Lose health from an attack. Defense blocks some damage,
     * but every hit does at least 1.                      <-- OVERRIDE ME
     * (A Boss might take only half damage, then call super.takeDamage.)
     */
    public void takeDamage(int amount)
    {
        int actual = amount - getDefense();
        if (actual < 1)
        {
            actual = 1;
        }
        health -= actual;
        if (health < 0)
        {
            health = 0;
        }
        System.out.println(name + " takes " + actual + " damage. ("
                           + health + "/" + maxHealth + ")");
    }

    /**
     * What this character does on THEIR turn in a fight.
     * By default, they just attack.                       <-- OVERRIDE ME
     * (A Boss might heal itself every third turn, or a Thief might steal gold.)
     */
    public void takeTurn(Character target)
    {
        attack(target);
    }

    // ------------------------------------------------------------
    // Meeting characters on the map
    // ------------------------------------------------------------

    /**
     * Is this character an enemy who will fight you on sight?
     * Default is true.                                    <-- OVERRIDE ME
     * (A Shopkeeper returns false.)
     */
    public boolean isHostile()
    {
        return true;
    }

    /**
     * What happens when the player talks to this character
     * (only used for characters who are NOT hostile).     <-- OVERRIDE ME
     * (A Shopkeeper would show a shop menu here.)
     */
    public void interact(Character visitor)
    {
        System.out.println(name + " nods at you but has nothing to say.");
    }

    // ------------------------------------------------------------
    // Recursion example
    // ------------------------------------------------------------

    /**
     * Total value of everything in the inventory.
     * This method starts a RECURSIVE helper at position 0.
     */
    public int getInventoryValue()
    {
        return valueFrom(0);
    }

    /**
     * Recursive helper: adds up the value of the items from
     * position "index" to the end of the inventory.
     *
     * Base case:      we ran off the end of the list -> nothing left, return 0.
     * Recursive case: this item's value + the value of all the items after it.
     */
    private int valueFrom(int index)
    {
        if (index >= inventory.size())
        {
            return 0;
        }
        return inventory.get(index).getValue() + valueFrom(index + 1);
    }

    /**
     * Text version of the character, e.g.  "Goblin (HP 12/20)"
     */
    public String toString()
    {
        return name + " (HP " + health + "/" + maxHealth + ")";
    }
}
